<script>
  import Seo from '#lib/components/Seo.svelte';
  // Vayu — /pages/cart.html, ported from public/pages/cart.html.
  import { onMount } from 'svelte';

  // Emitted through {@html} rather than written as a component <style>:
  // Svelte scopes component styles, and these selectors target markup
  // that the global stylesheet and other components own.
  const pageCss = "<style>/* ------------------------------------------------------------\n           Cart \u2014 minimal, compact.\n           Note: the global layer in styles.css forces\n           border-color: transparent !important, so separators here are\n           drawn as 1px pseudo-element backgrounds instead of borders.\n           ------------------------------------------------------------ */\n        /* no horizontal padding \u2014 this element is also .wrap, whose\n           --page-pad gutter is the only one the page should have (declaring\n           any value here, 0 included, would replace it) */\n        /* clearance for the mobile bottom nav \u2014 scoped to the widths where\n           that bar exists, so desktop does not carry 72px of dead space\n           between the last row and the footer */\n        @media (max-width: 768px) {\n            .cart-page {\n                padding-bottom: 72px;\n            }\n        }\n\n        /* ---------- header ---------- */\n        .cart-head {\n            display: flex;\n            align-items: baseline;\n            gap: 10px;\n            padding-bottom: 10px;\n        }\n\n        .cart-title {\n            font-family: 'Cormorant Garamond', serif;\n            font-size: clamp(22px, 2.4vw, 28px);\n            font-weight: 400;\n            color: var(--ink);\n            letter-spacing: 0.01em;\n            line-height: 1.1;\n            margin: 0;\n        }\n\n        .cart-count {\n            font-family: 'Jost', sans-serif;\n            font-size: 10.5px;\n            letter-spacing: 0.16em;\n            text-transform: uppercase;\n            color: #8A8681;\n            white-space: nowrap;\n        }\n\n        /* ---------- layout ---------- */\n        .cart-layout {\n            display: grid;\n            grid-template-columns: 1fr 268px;\n            gap: 40px;\n            align-items: start;\n        }\n\n        /* ---------- items ---------- */\n        .cart-item {\n            position: relative;\n            display: grid;\n            grid-template-columns: 88px 1fr auto;\n            gap: 14px;\n            align-items: center;\n            padding: 12px 0;\n            transition: opacity 0.28s ease;\n        }\n\n        /* hairline between rows only \u2014 no box, no outer rules */\n        .cart-item+.cart-item::before {\n            content: '';\n            position: absolute;\n            inset: 0 0 auto 0;\n            height: 1px;\n            background: #F0EDE7;\n        }\n\n        .cart-item.removing {\n            opacity: 0;\n        }\n\n        .cart-item-img {\n            width: 88px;\n            height: 88px;\n            overflow: hidden;\n            background: #FAF8F5;\n        }\n\n        .cart-item-img img {\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n            transition: transform 0.5s cubic-bezier(0.25, 1, 0.5, 1);\n        }\n\n        .cart-item:hover .cart-item-img img {\n            transform: scale(1.04);\n        }\n\n        .cart-item-link {\n            text-decoration: none;\n            color: inherit;\n            display: block;\n        }\n\n        .cart-item-cat {\n            font-family: 'Jost', sans-serif;\n            font-size: 9px;\n            letter-spacing: 0.16em;\n            text-transform: uppercase;\n            color: var(--gold);\n            font-weight: 500;\n            line-height: 1;\n            margin-bottom: 4px;\n        }\n\n        .cart-item-info h3 {\n            font-family: 'Cormorant Garamond', serif;\n            font-size: 15px;\n            font-weight: 500;\n            color: var(--ink);\n            margin: 0 0 6px;\n            line-height: 1.25;\n        }\n\n        /* ---------- quantity (flat, no chrome) ---------- */\n        .cart-qty {\n            display: inline-flex;\n            align-items: center;\n            gap: 4px;\n        }\n\n        .cart-qty-btn {\n            width: 20px;\n            height: 20px;\n            border: none;\n            background: transparent;\n            color: #8A8681;\n            font-size: 14px;\n            line-height: 1;\n            cursor: pointer;\n            display: grid;\n            place-items: center;\n            padding: 0;\n            transition: color 0.2s ease;\n        }\n\n        .cart-qty-btn:hover {\n            color: var(--accent);\n        }\n\n        .cart-qty-val {\n            font-family: 'Jost', sans-serif;\n            font-size: 12px;\n            color: var(--ink);\n            min-width: 16px;\n            text-align: center;\n            font-weight: 500;\n        }\n\n        /* ---------- right column: price over remove ---------- */\n        .cart-item-end {\n            display: flex;\n            flex-direction: column;\n            align-items: flex-end;\n            gap: 4px;\n        }\n\n        .cart-item-price {\n            font-family: 'Jost', sans-serif;\n            font-size: 13px;\n            color: var(--ink);\n            font-weight: 500;\n            white-space: nowrap;\n        }\n\n        .cart-remove {\n            background: none;\n            border: none;\n            color: #B4AFA8;\n            font-size: 15px;\n            line-height: 1;\n            cursor: pointer;\n            padding: 2px 4px;\n            transition: color 0.2s ease;\n        }\n\n        .cart-remove:hover {\n            color: var(--accent);\n        }\n\n        /* ---------- summary ---------- */\n        .cart-summary {\n            background: #FAF8F5;\n            padding: 16px 16px 18px;\n            position: sticky;\n            top: calc(var(--hdr-h, 58px) + 16px);\n        }\n\n        .cart-summary h2 {\n            font-family: 'Jost', sans-serif;\n            font-size: 10px;\n            letter-spacing: 0.18em;\n            text-transform: uppercase;\n            font-weight: 500;\n            color: #8A8681;\n            margin: 0 0 12px;\n        }\n\n        .cart-summary-row {\n            display: flex;\n            justify-content: space-between;\n            align-items: baseline;\n            padding: 5px 0;\n            font-family: 'Jost', sans-serif;\n            font-size: 12.5px;\n            color: var(--body);\n        }\n\n        .cart-summary-row span:last-child {\n            color: var(--ink);\n            font-weight: 500;\n        }\n\n        .cart-summary-total {\n            position: relative;\n            margin-top: 10px;\n            padding-top: 12px;\n        }\n\n        .cart-summary-total::before {\n            content: '';\n            position: absolute;\n            inset: 0 0 auto 0;\n            height: 1px;\n            background: #EAE5DC;\n        }\n\n        .cart-summary-total .cart-summary-row {\n            font-size: 14px;\n            padding: 0;\n            color: var(--ink);\n            font-weight: 500;\n        }\n\n        .cart-checkout-btn {\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            gap: 8px;\n            width: 100%;\n            padding: 11px;\n            background: var(--ink);\n            color: #fff;\n            border: none;\n            font-family: 'Jost', sans-serif;\n            font-size: 10.5px;\n            letter-spacing: 0.16em;\n            text-transform: uppercase;\n            font-weight: 500;\n            cursor: pointer;\n            margin-top: 14px;\n            transition: background 0.25s ease;\n        }\n\n        .cart-checkout-btn:hover {\n            background: var(--accent);\n        }\n\n        .cart-checkout-btn svg {\n            transition: transform 0.25s ease;\n        }\n\n        .cart-checkout-btn:hover svg {\n            transform: translateX(3px);\n        }\n\n        .cart-summary-note {\n            font-family: 'Jost', sans-serif;\n            font-size: 10px;\n            color: #8A8681;\n            text-align: center;\n            margin-top: 10px;\n            line-height: 1.5;\n        }\n\n        .cart-continue {\n            display: block;\n            text-align: center;\n            margin: 12px auto 0;\n            font-family: 'Jost', sans-serif;\n            font-size: 10.5px;\n            letter-spacing: 0.12em;\n            text-transform: uppercase;\n            color: var(--ink);\n            text-decoration: none;\n            font-weight: 500;\n            width: fit-content;\n            transition: color 0.2s ease;\n        }\n\n        .cart-continue:hover {\n            color: var(--accent);\n        }\n\n        /* ---------- empty state ---------- */\n        .cart-empty {\n            display: flex;\n            flex-direction: column;\n            align-items: center;\n            justify-content: center;\n            min-height: 40vh;\n            text-align: center;\n            padding: 32px 16px 40px;\n        }\n\n        .cart-empty-icon {\n            color: #C4BFB7;\n            margin-bottom: 16px;\n        }\n\n        .cart-empty-title {\n            font-family: 'Cormorant Garamond', serif;\n            font-weight: 400;\n            font-size: 22px;\n            color: var(--ink);\n            margin: 0 0 6px;\n        }\n\n        .cart-empty-text {\n            font-size: 12.5px;\n            color: var(--body);\n            max-width: 320px;\n            margin: 0 0 18px;\n            line-height: 1.6;\n        }\n\n        .cart-empty-btn {\n            display: inline-block;\n            padding: 11px 26px;\n            background: var(--ink);\n            color: #fff;\n            text-decoration: none;\n            font-size: 10.5px;\n            letter-spacing: 0.16em;\n            text-transform: uppercase;\n            font-family: 'Jost', sans-serif;\n            font-weight: 500;\n            transition: background 0.25s ease;\n        }\n\n        .cart-empty-btn:hover {\n            background: var(--accent);\n        }\n\n        /* ---------- responsive ---------- */\n        /* Desktop scale-up. The base sizing above is phone-first \u2014 64px\n           thumbnails, 15px names, a 268px summary \u2014 and on a 1440-1800px\n           column that read as a mobile layout stretched wide, with the\n           content occupying a thin band down the middle. Everything below\n           is proportion, not new structure: bigger plates, larger type, a\n           summary panel with real weight.\n\n           .cart-page declares no horizontal padding here \u2014 it shares its\n           element with .wrap, which owns the page gutter. */\n        @media (min-width: 1024px) {\n            .cart-head {\n                padding-bottom: 18px;\n                gap: 14px;\n            }\n\n            .cart-title {\n                font-size: 44px;\n            }\n\n            .cart-count {\n                font-size: 11.5px;\n            }\n\n            .cart-layout {\n                grid-template-columns: 1fr 440px;\n                gap: 64px;\n            }\n\n            /* the plate leads the row, so it sets the row's height */\n            .cart-item {\n                grid-template-columns: 180px 1fr auto;\n                gap: 34px;\n                padding: 28px 0;\n            }\n\n            .cart-item-img {\n                width: 180px;\n                height: 180px;\n            }\n\n            .cart-item-cat {\n                font-size: 10px;\n                margin-bottom: 7px;\n            }\n\n            .cart-item-info h3 {\n                font-size: 26px;\n                margin-bottom: 14px;\n            }\n\n            .cart-qty {\n                gap: 8px;\n            }\n\n            .cart-qty-btn {\n                width: 32px;\n                height: 32px;\n                font-size: 18px;\n                background: #FAF8F5;\n            }\n\n            .cart-qty-val {\n                font-size: 15px;\n                min-width: 26px;\n            }\n\n            .cart-item-end {\n                gap: 10px;\n            }\n\n            .cart-item-price {\n                font-size: 19px;\n            }\n\n            .cart-remove {\n                font-size: 19px;\n            }\n\n            .cart-summary {\n                padding: 32px 30px 34px;\n            }\n\n            .cart-summary h2 {\n                font-size: 12px;\n                margin-bottom: 22px;\n            }\n\n            .cart-summary-row {\n                font-size: 15.5px;\n                padding: 9px 0;\n            }\n\n            .cart-summary-total {\n                margin-top: 14px;\n                padding-top: 16px;\n            }\n\n            .cart-summary-total .cart-summary-row {\n                font-size: 21px;\n            }\n\n            .cart-checkout-btn {\n                padding: 18px;\n                font-size: 12.5px;\n                letter-spacing: 0.18em;\n                margin-top: 24px;\n            }\n\n            .cart-summary-note {\n                font-size: 11.5px;\n                margin-top: 16px;\n            }\n\n            .cart-continue {\n                font-size: 12px;\n                margin-top: 18px;\n            }\n\n            .cart-empty {\n                min-height: 52vh;\n            }\n\n            .cart-empty-icon {\n                width: 48px;\n                height: 48px;\n            }\n\n            .cart-empty-title {\n                font-size: 30px;\n            }\n\n            .cart-empty-text {\n                font-size: 14px;\n                max-width: 380px;\n            }\n\n            .cart-empty-btn {\n                padding: 14px 34px;\n                font-size: 11.5px;\n            }\n        }\n\n        @media (max-width: 900px) {\n            .cart-layout {\n                grid-template-columns: 1fr;\n                gap: 20px;\n            }\n\n            .cart-summary {\n                position: static;\n            }\n        }\n\n        @media (max-width: 600px) {\n            /* a little larger than the old 56px, so the piece is legible\n               at a glance on a phone */\n            .cart-item {\n                grid-template-columns: 78px 1fr auto;\n                gap: 14px;\n                padding: 12px 0;\n            }\n\n            .cart-item-img {\n                width: 78px;\n                height: 78px;\n            }\n        }\n/* The dialog scrolls; it used to simply overflow.\n           The card is as tall as the delivery form needs, the veil is\n           position: fixed, and neither of them could scroll — so on a short\n           phone the bottom of the form was off-screen with no way to reach\n           it. Measured at 320x568: the card ran to 714px and “Place order”\n           sat at y=700, 132px below the fold, and scrollIntoView moved\n           nothing. The form could be filled in and never submitted.\n\n           overflow-y: auto makes the veil the scroll container. The card is\n           centred with `margin: auto` rather than `place-items: center`,\n           because a centred grid item taller than its container overflows\n           equally in both directions and the top half becomes unreachable —\n           auto margins collapse to 0 instead of going negative, so the card\n           centres when it fits and pins to the top when it does not.\n\n           overscroll-behavior keeps a flick at the end of the form from\n           scrolling the cart page behind the dialog. */\n        .checkout-veil {\n            /* Above .mobile-bottom-nav, which is fixed at z-index 1002 and\n               was painting its 56px bar over the foot of the dialog on any\n               screen under 768px — across the submit button on a short one.\n               200 put the veil underneath it. */\n            position: fixed; inset: 0; z-index: 1100;\n            background: rgba(20, 18, 16, 0.45);\n            display: grid; padding: 20px;\n            overflow-y: auto;\n            overscroll-behavior: contain;\n            -webkit-overflow-scrolling: touch;\n        }\n        .checkout-card {\n            background: #fff; border-radius: 2px; padding: 26px 26px;\n            width: 100%; max-width: 520px; box-shadow: 0 30px 80px rgba(20, 18, 16, 0.3);\n            margin: auto;\n        }\n        .checkout-card h2 { font-family: 'Cormorant Garamond', serif; font-size: 24px; margin: 0 0 14px; }\n        .co-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 9px 12px; }\n        .co-grid .co-full { grid-column: 1 / -1; }\n        .co-grid label { display: grid; gap: 3px; font-size: 10px; letter-spacing: .12em; text-transform: uppercase; color: var(--body, #4E4A43); }\n        .co-grid input { padding: 7px 10px; border: 1px solid #e6e1d6; border-radius: 2px; font: inherit; font-size: 16px; line-height: 1.35; }\n        .co-grid input:focus { outline: 2px solid var(--accent, #9E3A26); outline-offset: -1px; }\n        /* Section 15 of styles.css sets `border-color: transparent\n           !important` on *, *::before and *::after, so every 1px border\n           declared above resolved to invisible: the fields, the address\n           picker and the secondary buttons were all unmarked white space on\n           a white card, which is why the form read as empty. The file’s own\n           note on that layer says elements must re-assert their colour with\n           !important afterwards — .co-google already did, and these did not.\n\n           A class selector carries more specificity than *, so these win the\n           !important contest rather than merely joining it. Desktop and\n           phone alike; this was never a mobile-only fault. */\n        .co-grid input,\n        .co-auth input,\n        .co-picker select { border-color: #d8d1c2 !important; }\n        .co-alt { border-color: #d8d1c2 !important; }\n        .co-summary { border-color: #e4ddcc !important; }\n        .co-grid input:focus,\n        .co-auth input:focus { border-color: var(--accent, #9E3A26) !important; }\n\n        .co-error { color: #b03030; font-size: 12.5px; min-height: 15px; margin: 8px 0 0; }\n        .co-actions { display: flex; gap: 12px; justify-content: flex-end; align-items: center; margin-top: 8px; flex-wrap: wrap; }\n\n        /* ---- sign in / register / guest ---- */\n        .co-loading { color: #8d887e; font-size: 14px; margin: 0; padding: 12px 0; text-align: center; }\n        .co-lede { color: #8d887e; font-size: 13.5px; line-height: 1.6; margin: -8px 0 18px; }\n        .co-choice { display: grid; gap: 10px; }\n        .co-choice .cart-checkout-btn { width: 100%; }\n        .co-alt {\n            padding: 10px 16px; background: #fff; border: 1px solid #e6e1d6; border-radius: 2px;\n            font: inherit; font-size: 13px; cursor: pointer; color: var(--body, #4E4A43);\n        }\n        .co-alt:hover { border-color: #141210; }\n        /* Google's button: their mark, our shape. !important on the border\n           because styles.css forces border-color: transparent on everything. */\n        .co-google {\n            display: flex; align-items: center; justify-content: center; gap: 10px;\n            padding: 10px 16px; border: 1px solid #C9C0AE !important; border-radius: 2px;\n            background: #fff; color: #141210; text-decoration: none;\n            font: inherit; font-size: 14px; cursor: pointer;\n            transition: border-color .2s ease, box-shadow .2s ease;\n        }\n        .co-google:hover { border-color: #141210 !important; box-shadow: 0 1px 6px rgba(20, 18, 16, .09); }\n        .co-google svg { flex: none; }\n\n        /* \"or\" with a rule through it, separating Google from the email form */\n        .co-or {\n            display: flex; align-items: center; gap: 12px;\n            margin: 14px 0; font-size: 12px; color: #8d887e;\n            text-transform: uppercase; letter-spacing: .14em;\n        }\n        .co-or::before, .co-or::after {\n            content: ''; flex: 1; height: 1px; background: #E6E1D6;\n        }\n\n        .co-auth { display: grid; gap: 9px; }\n        .co-auth label { display: grid; gap: 3px; font-size: 10px; letter-spacing: .12em; text-transform: uppercase; color: var(--body, #4E4A43); }\n        .co-auth input { padding: 7px 10px; border: 1px solid #e6e1d6; border-radius: 2px; font: inherit; font-size: 16px; line-height: 1.35; }\n        .co-auth input:focus { outline: 2px solid var(--accent, #9E3A26); outline-offset: -1px; }\n        .co-link {\n            background: none; border: 0; padding: 0; font: inherit; font-size: 13px;\n            text-decoration: underline; cursor: pointer; color: var(--body, #4E4A43);\n        }\n        .co-who { font-size: 13px; color: var(--body, #4E4A43); margin: -8px 0 14px; }\n        .co-who .co-link { margin-left: 6px; color: #8d887e; }\n        .co-summary {\n            background: #faf8f4; border: 1px solid #eee9dd; border-radius: 2px;\n            padding: 11px 13px; margin-bottom: 12px; font-size: 13.5px; line-height: 1.6;\n        }\n        .co-picker select {\n            padding: 7px 10px; border: 1px solid #e6e1d6; border-radius: 2px;\n            font: inherit; font-size: 16px; line-height: 1.35; background: #fff; width: 100%;\n        }\n        .co-check {\n            display: flex; align-items: center; gap: 8px; margin-top: 12px;\n            font-size: 13px; color: var(--body, #4E4A43);\n        }\n        .co-check input { width: 15px; height: 15px; }\n        .co-cancel { background: none; border: 0; cursor: pointer; font: inherit; font-size: 13px; text-decoration: underline; color: var(--body, #4E4A43); }\n        .co-submit { width: auto; padding: 12px 28px; }\n        .co-done { text-align: center; padding: 10px 0 4px; }\n        .co-done p { color: var(--body, #4E4A43); line-height: 1.7; margin: 10px 0 22px; }\n        @media (max-width: 520px) {\n            .co-grid { grid-template-columns: 1fr; }\n\n            /* Room back from the chrome: 34/32 of padding plus the veil’s\n               20 left a 320px screen about 216px of usable width. */\n            .checkout-veil { padding: 10px; }\n            .checkout-card { padding: 20px 16px; border-radius: 2px; }\n            .checkout-card h2 { font-size: 21px; margin-bottom: 12px; }\n\n            /* 16px is not a taste decision. Safari on iOS zooms the page\n               when a focused field is smaller than that, and the zoom is\n               not undone on blur — the shopper is left on a page wider\n               than the window, scrolled sideways, mid-form. These were\n               14px. */\n            .co-grid input,\n            .co-auth input,\n            .co-picker select { padding: 10px; }\n\n            /* Stacked and full width: side by side, “Place order” and the\n               link beside it were sharing a 216px row. The primary action\n               is first in the box and last in the DOM, so the tab order is\n               unchanged. */\n            .co-actions { flex-direction: column-reverse; align-items: stretch; gap: 10px; }\n            .co-submit { width: 100%; padding: 15px 20px; }\n            .co-cancel, .co-actions .co-link { padding: 6px 0; text-align: center; }\n\n            /* 15px is under the 24px minimum for a touch target. */\n            .co-check { align-items: flex-start; gap: 10px; }\n            .co-check input { width: 20px; height: 20px; flex: none; }\n        }</style>";

  onMount(() => {
    import('#lib/pages/cart.js').then(m => m.default?.());
  });
</script>

<Seo
  title="Your Cart"
  description="The pieces you are about to take home from Vayu."
  path="/pages/cart.html"
  noindex
/>

{@html pageCss}

<main class="wrap cart-page">
        <nav class="breadcrumb" aria-label="Breadcrumb">
            <a href="/index.html">Home</a>
            <span class="sep">|</span>
            <span>Your Cart</span>
        </nav>

        <!-- a <header> here would match the global `header &#123; position: fixed &#125;`
             desktop rule in styles.css and pin the title over the site nav -->
        <div class="cart-head">
            <h1 class="cart-title">Your Cart</h1>
            <!-- id is cartItemCount, not cartCount: the header badge in
                 partials/header.html already owns that id, so this element
                 was a duplicate and getElementById returned the header's.
                 The result was "3 items" rendered inside the small round
                 nav badge while this line stayed empty. -->
            <span class="cart-count" id="cartItemCount"></span>
        </div>

        <div id="cartContent"></div>
    </main>
